     1→# ABOUTME: Bisect test to find which part of num.t causes timeout
     2→# ABOUTME: Tests progressively larger portions of perl-num.t
     3→use 5.42.0;
     4→use experimental qw(class builtin);
     5→use Test::More;
     6→use Time::HiRes qw(time);
     7→use FindBin qw($RealBin);
     8→use lib "$RealBin/../lib";
     9→use Chalk::Grammar;
    10→use Chalk::Parser;
    11→use Chalk::Semiring::Boolean;
    12→use File::Spec;
    13→
    14→# Load grammar from BNF file
    15→my $bnf_file = File::Spec->catfile($RealBin, '..', 'grammar', 'perl.bnf');
    16→open my $grammar_fh, '<:utf8', $bnf_file or die "Cannot open $bnf_file: $!";
    17→my $bnf_content = do { local $/; <$grammar_fh> };
    18→close $grammar_fh;
    19→my $chalk_grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program');
    20→
    21→my $parser = Chalk::Parser->new(
    22→    grammar => $chalk_grammar,
    23→    semiring => Chalk::Semiring::Boolean->new(),
    24→);
    25→
    26→# Read the full file
    27→my @lines;
    28→{
    29→    open my $fh, '<', 'perl-num.t' or die "Cannot open perl-num.t: $!";
    30→    @lines = <$fh>;
    31→    close $fh;
    32→}
    33→
    34→my $total_lines = scalar(@lines);
    35→diag("Total lines in num.t: $total_lines");
    36→
    37→# Test progressively larger portions
    38→# Smaller tests should pass, larger ones are TODO until performance improves
    39→my @test_sizes = (10, 25, 50, 75, 100, 150, 200, $total_lines);
    40→
    41→for my $line_count (@test_sizes) {
    42→    last if $line_count > $total_lines;
    43→
    44→    # Mark tests >100 lines as TODO - they're too slow currently
