    16→
    17→# Load Chalk grammar from BNF file
    18→open my $fh, '<:utf8', 'grammar/chalk.bnf' or die "Cannot open chalk.bnf: $!";
    19→my $bnf_content = do { local $/; <$fh> };
    20→close $fh;
    21→my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program', 'Chalk');
    22→
    23→# Helper function to execute Chalk code via interpreter
    24→sub execute_chalk {
    25→    my ($code) = @_;
    26→
    27→    # Create Builder
    28→    my $builder = Chalk::IR::Builder->new();
    29→
    30→    # Create Parser with semantic actions
    31→    my $semiring = Chalk::Semiring::Semantic->new(
    32→        grammar => $grammar,
    33→        env => { ir_builder => $builder }
    34→    );
    35→
    36→    my $parser = Chalk::Parser->new(
    37→        grammar => $grammar,
    38→        semiring => $semiring,
    39→        preprocess => ['Chalk::Preprocessor::Heredoc']
    40→    );
    41→
    42→    # Parse the program
    43→    my $parse_result = $parser->parse_string($code);
    44→    return undef unless $parse_result;
    45→
    46→    # Get the IR graph
    47→    my $graph = $builder->graph;
    48→
    49→    # Prune graph to only include nodes from the winning parse
    50→    # The parse result's focus points to the winning Return node
    51→    if ($parse_result->can('context')) {
    52→        my $ctx = $parse_result->context;
    53→        if ($ctx->can('focus')) {
    54→            my $winning_node = $ctx->focus;
    55→            if ($winning_node && $winning_node->can('id')) {
    56→                $graph->prune_to_reachable($winning_node->id);
    57→            }
    58→        }
    59→    }
    60→
    61→    # Run GVN optimizer
    62→    my $gvn_result = Chalk::IR::Optimizer::GVN->run_gvn($graph);
    63→    $graph = $gvn_result->{graph};
    64→
    65→    # Execute via interpreter
    66→    my $interpreter = Chalk::IR::Interpreter->new(graph => $graph);
    67→    return $interpreter->execute();
    68→}
