        test_against_perl('return !1;', 'Not true (1)');
        test_against_perl('return !5;', 'Not truthy value');
        test_against_perl('my $x = 10; return !$x;', 'Not true variable');
    }
};

subtest 'TODO: Not operator with comparison expressions' => sub {
